(* [comment removed for export] *)
Lemma cut8_tail : forall B, CUTS B ->
  forall (r : Z) (a3v a4x a5x t6x s2x s3x s4x : word) rax ra sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11
    (F : bvmap 5 word) fc (m m1 : mem) (it0 I E lo shi : Z) (bs : list byte) (E0 : ecv) (g : bool) (j8 junk : list byte),
  chx_ctx m m1 sp s0v s1v s2v s3v s4v ra it0 I E lo shi bs r E0 g j8 junk -> chx_pure sp it0 I E lo shi bs E0 ->
  it0 <= r < it0 + Z.of_nat (length bs) ->
  4 * (it0 + Z.of_nat (length bs) - r) < B + 1 ->
  evt asegs (chx_post ra sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 F fc it0 I E lo shi bs E0 m)
    (MS (chx_regs rax (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp (wz r) a3v a4x a5x t6x s2x s3x s4x
                  I (it0 + Z.of_nat (length bs)) E s5 s6 s7 s8 s9 s10 s11)
