Lemma cuts_step : forall B, CUTS B -> CUTS (B + 1).
Proof.
  intros B IH c Hc.
  destruct c as [|[|[|[|[|[|[|[|[|[|c]]]]]]]]]]; [ | | | | | | | | | | exfalso; lia ].
  - apply cut0_step; assumption.
  - apply cut1_step; assumption.
  - apply cut2_step; assumption.
  - apply cut3_step; assumption.
  - apply cut4_step; assumption.
  - apply cut5_step; assumption.
  - apply cut6_step; assumption.
  - apply cut7_step; assumption.
  - apply cut8_step; assumption.
  - apply cut9_step; assumption.
Qed.

Lemma cuts_all : forall B, 0 <= B -> CUTS B.
Proof.
  intros B HB. pattern B. apply natlike_ind; [| | exact HB].
  - (* [comment removed for export] *)
    intros c Hc p w2 w3 w4 w5 w6 s2x s3x s4x rax ra sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 F fc m m1 it0 I E lo shi bs itv E0 g j8 junk.
    intros CTX PURE (ITV & P0 & PL) REL MEAS. exfalso.
    unfold cut_it in PL. unfold cut_rank in MEAS.
    destruct c as [|[|[|[|[|[|[|[|[|[|c]]]]]]]]]]; lia.
  - intros x Hx IH. replace (Z.succ x) with (x + 1) by lia. apply cuts_step. exact IH.
Qed.

